
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_m06_l_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_m06_l", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.944507457920388e-02, -4.944021301478600e-02, -4.944903733485870e-02, -4.949620883938328e-02, -4.964048932205154e-02, -5.001989025105862e-02, -5.094814154885769e-02, -5.302452676351902e-02, -5.628854430369165e-02, -5.210096910295049e-02, -2.240846770898365e-02, -8.373344947907341e-02, -3.196944205160665e-02, -2.459649390644876e-02, -2.631234040126062e-02, 1.622390108651828e-02, 4.955935452770516e-02, 1.805456059647156e-02, 2.085972008360088e-03, 8.562564701794850e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


